# PTX source for Group Normalization (fp16 input/output, fp32 accumulation) on SM80
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry gn_kernel (
    .param .u64   input_ptr,
    .param .u64   output_ptr,
    .param .u32   N,
    .param .u32   C,
    .param .u32   H,
    .param .u32   W,
    .param .u32   G
)
{
    // -------------------------------------------------------------------------
    // Thread / block indices
    // -------------------------------------------------------------------------
    .reg .u32   %tid, %bid;
    .reg .u64   %input, %output;
    .reg .u32   %n, %g, %cpg, %spatial, %M;
    .reg .u64   %base_offset;
    .reg .u32   %i, %stride;

    // Load parameters
    ld.param.u64    %input,    [input_ptr];
    ld.param.u64    %output,   [output_ptr];
    ld.param.u32    %n,        [N];
    ld.param.u32    %cpg,      [C];
    ld.param.u32    %spatial,  [H];
    ld.param.u32    %stride,   [W];           // reuse %stride as temporary
    ld.param.u32    %g,        [G];

    // Compute thread and block ids
    mov.u32         %tid, %tid.x;
    mov.u32         %bid, %ctaid.x;

    // -------------------------------------------------------------------------
    // Decode block id into sample (n) and group (g)
    // -------------------------------------------------------------------------
    .reg .u32   %tmp;
    // g = bid % G
    // n = bid / G
    rem.u32        %g, %bid, %g;          // %g now holds group index
    div.u32        %n, %bid, %g;          // %n now holds batch index

    // Compute channels per group
    // cpg = C / G   (C and G are passed as parameters)
    .reg .u32   %C, %G;
    ld.param.u32 %C, [C];
    ld.param.u32 %G, [G];
    div.u32        %cpg, %C, %G;          // channels per group

    // spatial = H * W
    mul.lo.u32     %spatial, %spatial, %stride;   // H * W

    // Total elements per group (M)
    mul.lo.u32     %M, %cpg, %spatial;   // M = channels_per_group * H * W

    // Base offset (in elements) for this (n, g) group:
    // base = ((n * C) + (g * cpg)) * spatial
    mul.lo.u32     %tmp, %n, %C;         // n * C
    mad.lo.u32     %tmp, %g, %cpg, %tmp; // n*C + g*cpg
    mul.lo.u64     %base_offset, %tmp, %spatial; // * spatial (as 64‑bit)

    // -------------------------------------------------------------------------
    // First pass: compute sum and sum of squares (fp32)
    // -------------------------------------------------------------------------
    .reg .f32   %sum, %sumsq, %x_f32;
    mov.f32     %sum, 0.0;
    mov.f32     %sumsq, 0.0;

    // Loop over elements with stride = blockDim.x (256)
    .reg .u32   %idx;
    mov.u32     %idx, %tid;
LOOP_SUM:
    setp.ge.u32 p1, %idx, %M;
    @p1 bra END_SUM;

    // element offset = base_offset + idx
    .reg .u64   %elem_offset;
    cvt.u64.u32 %elem_offset, %idx;
    mul.lo.u64  %elem_offset, %elem_offset, 2;          // fp16 = 2 bytes
    add.u64     %elem_offset, %base_offset, %elem_offset;

    // Load fp16, convert to fp32
    .reg .f16   %x_f16;
    ld.global.f16 %x_f16, [%input + %elem_offset];
    cvt.f32.f16 %x_f32, %x_f16;

    // Accumulate
    add.f32     %sum, %sum, %x_f32;
    mul.f32     %tmp_f32, %x_f32, %x_f32;
    add.f32     %sumsq, %sumsq, %tmp_f32;

    // idx += blockDim.x
    add.u32     %idx, %idx, 256;
    bra    LOOP_SUM;
END_SUM:

    // -------------------------------------------------------------------------
    // Reduction in shared memory
    // -------------------------------------------------------------------------
    .shared .align 4 .f32 s_sum[256];
    .shared .align 4 .f32 s_sumsq[256];
    .shared .align 4 .f32 s_mean;
    .shared .align 4 .f32 s_inv_std;

    // Store per‑thread partial results
    st.shared.f32 [s_sum+%tid*4], %sum;
    st.shared.f32 [s_sumsq+%tid*4], %sumsq;
    bar.sync 0;

    // Parallel reduction (tree)
    .reg .u32 %offset;
    mov.u32 %offset, 128;
REDUCTION_LOOP:
    setp.ge.u32 p2, %tid, %offset;
    @p2 bra SKIP_REDUCE;
    // sum += sum[tid+offset]
    ld.shared.f32 %tmp_f32, [s_sum+%tid*4 + %offset*4];
    ld.shared.f32 %x_f32,   [s_sum+%tid*4];
    add.f32 %x_f32, %x_f32, %tmp_f32;
    st.shared.f32 [s_sum+%tid*4], %x_f32;

    // sumsq += sumsq[tid+offset]
    ld.shared.f32 %tmp_f32, [s_sumsq+%tid*4 + %offset*4];
    ld.shared.f32 %x_f32,   [s_sumsq+%tid*4];
    add.f32 %x_f32, %x_f32, %tmp_f32;
    st.shared.f32 [s_sumsq+%tid*4], %x_f32;
SKIP_REDUCE:
    bar.sync 0;
    shr.u32 %offset, %offset, 1;
    setp.ne.u32 p3, %offset, 0;
    @p3 bra REDUCTION_LOOP;

    // Thread 0 now holds total sum and sumsq
    .reg .f32 %total_sum, %total_sumsq;
    @%tid EQ p4, %tid, 0;
    @p4 {
        ld.shared.f32 %total_sum, [s_sum];
        ld.shared.f32 %total_sumsq, [s_sumsq];
        // Compute mean and variance
        cvt.f32.u32 %tmp_f32, %M;               // M as float
        div.f32 %mean, %total_sum, %tmp_f32;    // mean = sum / M
        div.f32 %tmp_f32, %total_sumsq, %tmp_f32; // avg_sq = sumsq / M
        mul.f32 %x_f32, %mean, %mean;           // mean^2
        sub.f32 %var, %tmp_f32, %x_f32;         // var = avg_sq - mean^2
        // eps = 1e-5
        .reg .f32 %eps;
        mov.f32 %eps, 1e-05;
        add.f32 %var, %var, %eps;
        sqrt.approx.f32 %tmp_f32, %var;
        rcp.approx.f32 %inv_std, %tmp_f32;      // 1 / sqrt(var+eps)

        // Store for other threads
        st.shared.f32 [s_mean], %mean;
        st.shared.f32 [s_inv_std], %inv_std;
    }
    bar.sync 0;

    // Load mean & inv_std
    ld.shared.f32 %mean, [s_mean];
    ld.shared.f32 %inv_std, [s_inv_std];

    // -------------------------------------------------------------------------
    // Second pass: write normalized output
    // -------------------------------------------------------------------------
    mov.u32 %idx, %tid;
LOOP_WRITE:
    setp.ge.u32 p5, %idx, %M;
    @p5 bra END_WRITE;

    // element offset = base_offset + idx
    cvt.u64.u32 %elem_offset, %idx;
    mul.lo.u64  %elem_offset, %elem_offset, 2;
    add.u64     %elem_offset, %base_offset, %elem_offset;

    // Load fp16, convert to fp32
    ld.global.f16 %x_f16, [%input + %elem_offset];
    cvt.f32.f16 %x_f32, %x_f16;

    // Normalize: (x - mean) * inv_std
    sub.f32 %tmp_f32, %x_f32, %mean;
    mul.f32 %tmp_f32, %tmp_f32, %inv_std;

    // Convert back to fp16 and store
    cvt.f16.f32 %x_f16, %tmp_f32;
    st.global.f16 [%output + %elem_offset], %x_f16;

    // idx += blockDim.x
    add.u32 %idx, %idx, 256;
    bra LOOP_WRITE;
END_WRITE:
    ret;
}
'''

