class ModelNew:
    def __init__(self, num_features, num_groups):
        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)
        self.num_features = num_features
        self.num_groups   = num_groups

    def __call__(self, x):
        # x: torch.Tensor (float16) on CUDA
        assert x.is_cuda and x.dtype == torch.float16
        out = torch.empty_like(x)

        N, C, H, W = x.shape
        # Grid: one block per (batch, group)
        grid = (N * self.num_groups, )
        block = (256, )

        args = [
            x.data_ptr(),
